\title{Weighted Quantum Signal Processing: Low-Depth Polynomial Approximation with Applications to Kolmogorov–Arnold Networks}

\author{Rohit Sarma Sarkar}
\email{rohit15sarkar@yahoo.com}
\affiliation{Universitat Polit\`ecnica de Catalunya, Barcelona, Spain}

\author{Rupayan Bhattacharjee}
