\begin{eqnarray}\label{QSPnew}
U^{\mathrm{QSP}}_{\boldsymbol{\Phi}}(x)
=
\left(
\prod_{j=1}^{k}
R_z(\phi_j)U(x)
\right)
\end{eqnarray}
and
\begin{eqnarray}\label{WQSPnew}
U^{\mathrm{WQSP}}_{\boldsymbol{\Phi}_{\mathbf{w}}}(x)
=
\left(
\prod_{j=1}^{k}
R_z(\phi_j)U(x)^{w_j}
\right).
\end{eqnarray}

