    \item For any weight vector $\mathbf{w}$, whenever $M_k\mathbf{w}$ or $\mathcal{R}_{\mathbf{w}}$ don't produce distinct elements, the main idea is to always find the rows of $N_k$ corresponding to the similar elements $c_{r_j}$ and collapse them into a single row vector via addition.
    \item It is also of note that the polynomials in Theorem \ref{WQSPsum} and as a consequence polynomials in Corollary \ref{QSPsum} harbors some interesting properties already observed in \cite{gilyen}.
\end{enumerate}

\end{remark}

\begin{corollary}\label{wqspcoro}
    Let $\mathbf{w} = (w_1, \dots, w_k) \in \mathbb{N}^k$ be a fixed weight vector and $N = \sum_{j=1}^k w_j$. Let $P(x)=\bra{0}U^{\mathrm{WQSP}}_{\boldsymbol{\Phi},\mathbf{w}}(x)\ket{0}$ and $R(x)=\frac{1}{i\sqrt{1-x^2}}\bra{0}U^{\mathrm{WQSP}}_{\boldsymbol{\Phi},\mathbf{w}}(x)\ket{1}$. Then, 
\begin{enumerate}
    \item $P(x)\in \mathbb{C}[x]$ and $|P(x)| \le 1$ for all $x \in [-1, 1]$.
    \item $P(x)$ has parity $N \pmod 2$ and $R(x)\in \mathbb{C}[x]$ has parity $N-1 \pmod 2$.
    \item  $|P(x)|^2+(1-x^2)|R(x)|^2=1$.
\end{enumerate}
\end{corollary}
